	    [Ignore]
	    private void SaveAllRepresentations()
	    {
	        List<EntityChange> entityChanges = new List<EntityChange>();
				
	        SaveBufferRepresentationsOfTcsParametroValor(entityChanges);		
				
	        SaveBufferRepresentationsOfTcsParametroValorUsuario(entityChanges);		
				
	        SaveBufferRepresentationsOfTcsParametroValorRede(entityChanges);		
				
	        SaveBufferRepresentationsOfTcsParametroValorGpecon(entityChanges);		
				
	        SaveBufferRepresentationsOfTcsParametroValorFilial(entityChanges);		
				
	        SaveBufferRepresentationsOfTcsParametroValorLjvLoja(entityChanges);		
				
	        SaveBufferRepresentationsOfTcsParametroValorVariacaoGenerica(entityChanges);		
				
	        SaveBufferRepresentationsOfTcsParametroValorP(entityChanges);		
				
	        SaveBufferRepresentationsOfTcsParametroValorLojaP(entityChanges);		
				
	        SaveBufferRepresentationsOfTcsParametroValorUsuarioP(entityChanges);		
				
	        SaveBufferRepresentationsOfTcsParametroValorRedeP(entityChanges);		
				
	        SaveBufferRepresentationsOfTcsParametroValorGpeconP(entityChanges);		
				
	        SaveBufferRepresentationsOfTcsParametroValorFilialP(entityChanges);		
				
	        SaveBufferRepresentationsOfTcsParametroValorVariacaoGenericaP1(entityChanges);		
		
	        if (entityChanges.Count == 0) return;
		
 
 	        //Submitting all data changes
 	        Linx.Framework.BV.Parametro.ParametroDomainService serviceContext0 = new Linx.Framework.BV.Parametro.ParametroDomainService(this.GetEDM(), this.Headers) { IsSecure = this.IsSecure };
 	        var serviceContext0Changes = entityChanges.Where(e => e.Mark == "serviceContext0").ToList();
 	        serviceContext0.SubmitData(this.ServiceContext, serviceContext0Changes);
 	        //Replace keys from source
 	        foreach (var entityChange in serviceContext0Changes) { entityChange.RefreshKeys(); this.ReplaceDetailsByParent(entityChanges, entityChange.Representation); }
 	        Linx.Framework.BV.Parametro.ParametroDomainService serviceContext1 = new Linx.Framework.BV.Parametro.ParametroDomainService(this.Headers) { IsSecure = this.IsSecure };
 	        var serviceContext1Changes = entityChanges.Where(e => e.Mark == "serviceContext1").ToList();
 	        serviceContext1.SubmitData(this.ServiceContext, serviceContext1Changes);
 	        //Replace keys from source
 	        foreach (var entityChange in serviceContext1Changes) { entityChange.RefreshKeys(); this.ReplaceDetailsByParent(entityChanges, entityChange.Representation); }	

	    }

			
	  
