	    #region Excluded Filters
	
	    private List<string> GetExcludedFilters()
	    {
	    	List<string> result = new List<string>();
	    	result.Add("TcsParametro|ColunaCodValida");
	    	result.Add("TcsParametro|TCS_PARAMETRO_AUTORIZACAO.COLUNA_COD_VALIDA");
	    	result.Add("TcsParametro|ColunaDescValida");
	    	result.Add("TcsParametro|TCS_PARAMETRO_AUTORIZACAO.COLUNA_DESC_VALIDA");
	    	result.Add("TcsParametro|FaixaFinal");
	    	result.Add("TcsParametro|TCS_PARAMETRO_AUTORIZACAO.FAIXA_FINAL");
	    	result.Add("TcsParametro|FaixaInicial");
	    	result.Add("TcsParametro|TCS_PARAMETRO_AUTORIZACAO.FAIXA_INICIAL");
	    	result.Add("TcsParametro|ObsParametro");
	    	result.Add("TcsParametro|TCS_PARAMETRO_AUTORIZACAO.OBS_PARAMETRO");
	    	//Add filtering disabled property for TCS_PARAMETRO_VALOR
	    	string[] bmDisabledTcsParametroValorVariacaoPList = this.GetEDM().GetFilteringDisabledList("TCS_PARAMETRO_VALOR");
	    	if (bmDisabledTcsParametroValorVariacaoPList.Length > 0)
	    	{
	
	    		if (bmDisabledTcsParametroValorVariacaoPList.Contains("TCS_PARAMETRO_VALOR.CHAVE_SELECAO"))
	    		{
	    			result.Add("TcsParametroValorVariacaoP|ChaveSelecao");
	    			result.Add("TcsParametroValorVariacaoP|TCS_PARAMETRO_VALOR.CHAVE_SELECAO");
	    		}
	
	    		if (bmDisabledTcsParametroValorVariacaoPList.Contains("TCS_PARAMETRO_VALOR.ID_PARAMETRO"))
