	         string serializedEntitySearch = SerializationManager<List<EntitySearch>>.ObjectToString(queryFilters);
	         return (from r in this.GetTcsParametroByEntitySearchNoAssociations(serializedEntitySearch) select r).FirstOrDefault();
	    }


