	    [Ignore()]
	    private void SetTcsUsuarioParametroBusinessFilter(ref IQueryable<TcsUsuarioParametro> query, List<EntitySearch> entitySearchList)
	    {
	    		int idxElement;
	    		string operatorValue;
	    		object value;
	    		//Get query by functions
	    		if (entitySearchList.Count > 0)
	    		{
	    			foreach (EntitySearch search in entitySearchList.Where(e => e.EntityName == "TcsUsuarioParametro"))
	    			{

	
	    				foreach (var exp in search.Expressions.Where(e => e.Name == "Field" && (e.Value.ToString() == "UidUsuarioString" || e.Value.ToString() == "TCS_USUARIO.UID_USUARIO.ToString()")))
	    				{
	    					idxElement = search.Expressions.IndexOf(exp);
	    					if ((idxElement + 2) < search.Expressions.Count)
	    					{
	    						if (search.Expressions[idxElement + 1].Name == "Operator" && search.Expressions[idxElement + 2].Name == "Value")
	    						{
	    								operatorValue = search.Expressions[idxElement + 1].Value.ToString();
	    								value = search.Expressions[idxElement + 2].Value;
	    								if (value.IsNullOrEmpty())
												continue;

	
	    								//Adjust Like operator
	    								if (operatorValue == "Like")
	    								{
	    								    string enteredVal = value.ToString();
	    								    if (enteredVal.Right(1) == "%" && enteredVal.Left(1) == "%")
	    								    {
	    								        enteredVal = enteredVal.Replace("%", "");
	    								        operatorValue = "Contains";
	    								    }
	    								    else if (enteredVal.Left(1) == "%")
	    								    {
	    								        enteredVal = enteredVal.Replace("%", "");
	    								        operatorValue = "EndsWith";
	    								    }
	    								    else
	    								    {
	    								        enteredVal = enteredVal.Replace("%", "");
	    								        operatorValue = "StartsWith";
	    								    }
	    								    value = enteredVal;
	    								}

	
	    								switch (operatorValue)
	    								{
	    									case "==":
	    										string tmpUidUsuarioString1 = (string)value;
	    										query = from r in query where r.UidUsuarioString == tmpUidUsuarioString1 select r;
	    										break;
	    									case "!=":
	    										string tmpUidUsuarioString2 = (string)value;
	    										query = from r in query where r.UidUsuarioString != tmpUidUsuarioString2 select r;
	    										break;

	
	    									case "Contains":
	    										string tmpUidUsuarioString7 = (string)value;
	    									    query = from r in query where r.UidUsuarioString.Contains(tmpUidUsuarioString7) select r;
	    									    break;
	    									case "StartsWith":
	    										string tmpUidUsuarioString8 = (string)value;
	    									    query = from r in query where r.UidUsuarioString.StartsWith(tmpUidUsuarioString8) select r;
	    									    break;
	    									case "EndsWith":
	    										string tmpUidUsuarioString9 = (string)value;
	    									    query = from r in query where r.UidUsuarioString.EndsWith(tmpUidUsuarioString9) select r;
	    									    break;

	
	    									default:
	    										break;
	    								}                                
	    							}
	    						}
        					} 

    	
	    				}
	    			}   
	    }


		
	
	    
