	    [Ignore()]
	    private void SetLjvLojaParametroBusinessFilter(ref IQueryable<LjvLojaParametro> query, List<EntitySearch> entitySearchList)
	    {
	    		int idxElement;
	    		string operatorValue;
	    		object value;
	    		//Get query by functions
	    		if (entitySearchList.Count > 0)
	    		{
	    			foreach (EntitySearch search in entitySearchList.Where(e => e.EntityName == "LjvLojaParametro"))
	    			{

	
	    				foreach (var exp in search.Expressions.Where(e => e.Name == "Field" && (e.Value.ToString() == "IdLojaString" || e.Value.ToString() == "LJV_LOJA.ID_LOJA.ToString()")))
	    				{
	    					idxElement = search.Expressions.IndexOf(exp);
	    					if ((idxElement + 2) < search.Expressions.Count)
	    					{
	    						if (search.Expressions[idxElement + 1].Name == "Operator" && search.Expressions[idxElement + 2].Name == "Value")
	    						{
	    								operatorValue = search.Expressions[idxElement + 1].Value.ToString();
	    								value = search.Expressions[idxElement + 2].Value;
	    								if (value.IsNullOrEmpty())
												continue;

	
	    								//Adjust Like operator
	    								if (operatorValue == "Like")
	    								{
	    								    string enteredVal = value.ToString();
	    								    if (enteredVal.Right(1) == "%" && enteredVal.Left(1) == "%")
	    								    {
	    								        enteredVal = enteredVal.Replace("%", "");
	    								        operatorValue = "Contains";
	    								    }
	    								    else if (enteredVal.Left(1) == "%")
	    								    {
	    								        enteredVal = enteredVal.Replace("%", "");
	    								        operatorValue = "EndsWith";
	    								    }
	    								    else
	    								    {
	    								        enteredVal = enteredVal.Replace("%", "");
	    								        operatorValue = "StartsWith";
	    								    }
	    								    value = enteredVal;
	    								}

	
	    								switch (operatorValue)
	    								{
	    									case "==":
	    										string tmpIdLojaString1 = (string)value;
	    										query = from r in query where r.IdLojaString == tmpIdLojaString1 select r;
	    										break;
	    									case "!=":
	    										string tmpIdLojaString2 = (string)value;
	    										query = from r in query where r.IdLojaString != tmpIdLojaString2 select r;
	    										break;

	
	    									case "Contains":
	    										string tmpIdLojaString7 = (string)value;
	    									    query = from r in query where r.IdLojaString.Contains(tmpIdLojaString7) select r;
	    									    break;
	    									case "StartsWith":
	    										string tmpIdLojaString8 = (string)value;
	    									    query = from r in query where r.IdLojaString.StartsWith(tmpIdLojaString8) select r;
	    									    break;
	    									case "EndsWith":
	    										string tmpIdLojaString9 = (string)value;
	    									    query = from r in query where r.IdLojaString.EndsWith(tmpIdLojaString9) select r;
	    									    break;

	
	    									default:
	    										break;
	    								}                                
	    							}
	    						}
        					} 

    	
	    				}
	    			}   
	    }


		
	
	    
